pack(26, "C1", T("Advanced 2: Idioms & Mexican slang", "Cao cấp 2: Thành ngữ & tiếng lóng Mexico"),
     T("Sound like a local with everyday expressions.", "Nói như người bản xứ với các cách diễn đạt đời thường."),
 [lesson("slang", T("Mexican slang", "Tiếng lóng Mexico"), T("Casual words you'll hear every day.", "Những từ thân mật bạn sẽ nghe mỗi ngày."), "smile", [
    ("¡Qué padre!", "How cool!", "Hay quá! / Đỉnh ghê!"),
    ("¡No manches!", "No way! / You're kidding!", "Không thể nào! / Đùa à!", "Very casual; avoid it in formal settings.", "Rất thân mật; tránh dùng khi trang trọng."),
    ("¿Qué onda?", "What's up?", "Sao rồi? / Có gì không?"),
    ("Ahorita lo hago.", "I'll do it in a bit (or… eventually).", "Tôi làm ngay đây (hoặc… lát nữa).", "“Ahorita” can mean now, soon, or much later!", "“Ahorita” có thể là ngay, lát nữa hoặc rất lâu nữa!"),
    ("Está chido.", "It's cool / nice.", "Hay đấy / Được đấy."),
    ("¡Aguas!", "Watch out!", "Coi chừng!")],
    focus=T("Slang is for friends. In formal settings, switch back to neutral Spanish.", "Tiếng lóng chỉ dùng với bạn bè. Khi trang trọng, quay lại tiếng Tây Ban Nha chuẩn.")),
  lesson("idioms", T("Common idioms", "Thành ngữ thông dụng"), T("Expressions that don't translate word for word.", "Những cách nói không dịch từng chữ được."), "feather", [
    ("Me cayó el veinte.", "The penny dropped. / I finally got it.", "Giờ tôi mới vỡ lẽ."),
    ("Estoy hasta el gorro.", "I'm fed up.", "Tôi chán ngấy rồi."),
    ("Es pan comido.", "It's a piece of cake.", "Dễ như ăn bánh."),
    ("Echarle ganas.", "To give it your all.", "Cố gắng hết sức."),
    ("No tiene pelos en la lengua.", "He doesn't mince his words.", "Anh ta ăn nói thẳng thừng."),
    ("Más vale tarde que nunca.", "Better late than never.", "Muộn còn hơn không.")],
    focus=T("Learn idioms as whole chunks, with the situation they belong to.", "Học thành ngữ theo cả cụm, gắn với tình huống sử dụng."))],
 [convo("friends-hangout", T("Hang out with friends", "Đi chơi với bạn bè"), T("Keep up with casual Mexican Spanish.", "Theo kịp tiếng Tây Ban Nha Mexico thân mật."), "heart", [
    node("hi", "¡Qué onda! ¿Cómo te fue en el examen?", "What's up! How did the exam go?", "Sao rồi! Thi cử thế nào?", "Answer casually, maybe with an idiom.", "Trả lời thân mật, có thể dùng thành ngữ.",
      ok("easy", "¡Bien! Fue pan comido.", "Good! It was a piece of cake.", "Ổn! Dễ như ăn bánh.", "¡Qué padre! Hay que celebrar.", "How cool! We have to celebrate.", "Đỉnh thật! Phải ăn mừng thôi.", "plan"),
      ok("hard", "Uf, difícil, pero le eché ganas.", "Ugh, tough, but I gave it my all.", "Ôi, khó lắm, nhưng mình đã cố hết sức.", "Eso es lo importante. Vamos a celebrar.", "That's what matters. Let's celebrate.", "Thế là được rồi. Đi ăn mừng nào.", "plan"),
      bad("formal", "Estimado amigo, el examen transcurrió de forma satisfactoria.", "Dear friend, the exam proceeded satisfactorily.", "Bạn thân mến, kỳ thi đã diễn ra tốt đẹp.", "¡Bien! Fue pan comido.", "Jaja, ¡qué formal! Relájate, wey.", "Haha, so formal! Relax, dude.", "Haha, trang trọng thế! Thả lỏng đi bạn.", "plan")),
    node("plan", "¿Vamos por unos tacos ahorita?", "Shall we go for some tacos now(ish)?", "Đi ăn tacos giờ (hoặc lát nữa) không?", "Ask what “ahorita” means here, or agree.", "Hỏi “ahorita” ở đây là khi nào, hoặc đồng ý.",
      ok("now", "¿Ahorita ahorita o ahorita en un rato?", "Like right now, or “ahorita” in a while?", "Ngay bây giờ hay một lúc nữa?", "Jaja, ahorita ahorita. ¡Vámonos!", "Haha, right now. Let's go!", "Haha, ngay bây giờ. Đi thôi!", "taco"),
      ok("yes", "¡Está chido! Vámonos.", "Cool! Let's go.", "Được đấy! Đi thôi.", "¡Órale! Conozco un lugar buenísimo.", "Alright! I know a great place.", "Ok luôn! Mình biết một chỗ ngon lắm.", "taco"),
      bad("slow", "Más vale tarde que nunca.", "Better late than never.", "Muộn còn hơn không.", "¡Está chido! Vámonos.", "¿Eso es un sí? Jaja, vámonos.", "Is that a yes? Haha, let's go.", "Thế là đồng ý à? Haha, đi thôi.", "taco")),
    node("taco", "¡Aguas! Esa salsa pica muchísimo.", "Watch out! That salsa is really spicy.", "Coi chừng! Sốt đó cay lắm đấy.", "React naturally.", "Phản ứng tự nhiên.",
      ok("manches", "¡No manches, pica demasiado!", "No way, it's way too spicy!", "Trời ơi, cay quá trời!", "¡Te dije! Toma agua.", "I told you! Have some water.", "Đã bảo mà! Uống nước đi."),
      ok("thanks", "Gracias por avisar. Mejor la verde.", "Thanks for the heads-up. The green one's better.", "Cảm ơn đã nhắc. Lấy sốt xanh thôi.", "Buena decisión.", "Good call.", "Chọn đúng đấy."),
      bad("water", "¿Dónde está el agua?", "Where is the water?", "Nước ở đâu?", "¡No manches, pica demasiado!", "Jaja, ya te picó, ¿verdad? Aquí está el agua.", "Haha, it already got you, right? Here's the water.", "Haha, cay rồi phải không? Nước đây."))])])

