pack(27, "C1", T("Advanced 3: Formal Spanish at work", "Cao cấp 3: Tiếng Tây Ban Nha trang trọng nơi công sở"),
     T("Emails, meetings, and professional tone.", "Email, cuộc họp và giọng điệu chuyên nghiệp."),
 [lesson("emails", T("Professional emails", "Email công việc"), T("Open, request, and close formally.", "Mở đầu, đề nghị và kết thúc trang trọng."), "mail", [
    ("Estimada licenciada García:", "Dear Ms. García:", "Kính gửi bà García:", "Mexicans often use titles: licenciado/a, ingeniero/a, doctor/a.", "Người Mexico hay dùng danh xưng: licenciado/a, ingeniero/a, doctor/a."),
    ("Le escribo para solicitar información sobre…", "I'm writing to request information about…", "Tôi viết thư này để xin thông tin về…"),
    ("Le agradecería que me enviara el informe.", "I would appreciate it if you sent me the report.", "Tôi rất cảm kích nếu bà gửi cho tôi bản báo cáo."),
    ("Adjunto encontrará el documento.", "Please find the document attached.", "Tài liệu được đính kèm."),
    ("Quedo atento a sus comentarios.", "I look forward to your comments.", "Tôi chờ ý kiến phản hồi của bà."),
    ("Saludos cordiales.", "Kind regards.", "Trân trọng.")],
    focus=T("“Le agradecería que + past subjunctive” is the most polite way to request something in writing.", "“Le agradecería que + giả định quá khứ” là cách lịch sự nhất để đề nghị trong văn viết.")),
  lesson("meetings", T("Meetings", "Cuộc họp"), T("Lead and take part in meetings.", "Điều phối và tham gia cuộc họp."), "users", [
    ("Si les parece, empezamos.", "If you all agree, let's begin.", "Nếu mọi người đồng ý, ta bắt đầu."),
    ("El primer punto del orden del día es…", "The first item on the agenda is…", "Mục đầu tiên trong chương trình là…"),
    ("Perdón que interrumpa, pero…", "Sorry to interrupt, but…", "Xin lỗi đã ngắt lời, nhưng…"),
    ("¿Podría ampliar un poco esa idea?", "Could you expand on that idea a bit?", "Anh/chị có thể nói rõ hơn ý đó không?"),
    ("Retomando lo que decía Luis…", "Going back to what Luis was saying…", "Quay lại ý anh Luis vừa nói…"),
    ("Para resumir, acordamos que…", "To sum up, we agreed that…", "Tóm lại, chúng ta thống nhất rằng…")],
    focus=T("Use “usted/ustedes” and softeners like “si les parece” to keep meetings polite.", "Dùng “usted/ustedes” và những câu làm mềm như “si les parece” để cuộc họp lịch sự."))],
 [convo("meeting", T("Lead a team meeting", "Điều phối cuộc họp nhóm"), T("Open, manage, and close a meeting professionally.", "Mở đầu, điều phối và kết thúc cuộc họp chuyên nghiệp."), "briefcase", [
    node("open", "Ya estamos todos. Cuando quieras.", "We're all here. Whenever you're ready.", "Mọi người đủ rồi. Bạn bắt đầu đi.", "Open the meeting formally.", "Mở đầu cuộc họp trang trọng.",
      ok("start", "Muy bien, si les parece, empezamos. El primer punto es el presupuesto.", "Great, if you all agree, let's begin. The first item is the budget.", "Được, nếu mọi người đồng ý thì ta bắt đầu. Mục đầu tiên là ngân sách.", "Perdón que interrumpa, pero ¿no íbamos a ver primero las fechas?", "Sorry to interrupt, but weren't we going to look at dates first?", "Xin lỗi ngắt lời, nhưng không phải ta xem lịch trước sao?", "interrupt"),
      ok("thanks", "Gracias por venir. El primer punto del orden del día es el presupuesto.", "Thanks for coming. The first item on the agenda is the budget.", "Cảm ơn mọi người đã đến. Mục đầu tiên trong chương trình là ngân sách.", "Perdón que interrumpa, ¿podemos ver primero las fechas?", "Sorry to interrupt, can we look at dates first?", "Xin lỗi ngắt lời, ta xem lịch trước được không?", "interrupt"),
      bad("slang", "¿Qué onda, banda? Empezamos.", "What's up, gang? Let's start.", "Sao rồi cả nhà? Bắt đầu thôi.", "Muy bien, si les parece, empezamos. El primer punto es el presupuesto.", "Mmm, es una junta con el director… mejor más formal.", "Hmm, it's a meeting with the director… better be more formal.", "Ừm, họp với giám đốc đấy… nên trang trọng hơn.", "interrupt")),
    node("interrupt", "Creo que las fechas son más urgentes.", "I think the dates are more urgent.", "Tôi nghĩ lịch trình gấp hơn.", "Handle the interruption politely.", "Xử lý việc bị ngắt lời một cách lịch sự.",
      ok("expand", "Buen punto. ¿Podría ampliar un poco por qué?", "Good point. Could you expand a bit on why?", "Ý hay. Anh/chị nói rõ hơn vì sao được không?", "Porque el cliente quiere el proyecto en marzo.", "Because the client wants the project in March.", "Vì khách hàng muốn dự án xong trong tháng Ba.", "close"),
      ok("agree", "De acuerdo, cambiamos el orden. Hablemos de las fechas.", "Agreed, let's change the order. Let's talk dates.", "Đồng ý, ta đổi thứ tự. Bàn về lịch trình nhé.", "Gracias. El cliente quiere todo para marzo.", "Thanks. The client wants everything by March.", "Cảm ơn. Khách hàng muốn mọi thứ xong trước tháng Ba.", "close"),
      bad("rude", "No, primero el presupuesto.", "No, budget first.", "Không, ngân sách trước.", "Buen punto. ¿Podría ampliar un poco por qué?", "Está bien… aunque las fechas son importantes.", "OK… although the dates are important.", "Được thôi… dù lịch trình cũng quan trọng.", "close")),
    node("close", "Creo que ya cubrimos todo.", "I think we've covered everything.", "Tôi nghĩ ta đã bàn hết rồi.", "Summarize and close.", "Tóm tắt và kết thúc.",
      ok("summary", "Para resumir, acordamos entregar en marzo y revisar el presupuesto. Les envío la minuta.", "To sum up, we agreed to deliver in March and review the budget. I'll send you the minutes.", "Tóm lại, ta thống nhất giao trong tháng Ba và xem lại ngân sách. Tôi sẽ gửi biên bản cho mọi người.", "Perfecto, muchas gracias.", "Perfect, thank you very much.", "Tuyệt, cảm ơn nhiều."),
      ok("next", "Muy bien. Para resumir: fechas en marzo; la próxima semana vemos el presupuesto.", "Great. To sum up: dates in March; next week we'll look at the budget.", "Được. Tóm lại: lịch trình trong tháng Ba; tuần sau xem ngân sách.", "De acuerdo. ¡Buen trabajo!", "Agreed. Good job!", "Đồng ý. Làm tốt lắm!"),
      bad("bye", "¡Bye!", "Bye!", "Bye!", "Para resumir, acordamos entregar en marzo y revisar el presupuesto. Les envío la minuta.", "¿Y el resumen? Siempre es bueno cerrar con los acuerdos.", "And the summary? It's always good to close with the agreements.", "Còn phần tóm tắt? Nên kết thúc bằng các điểm đã thống nhất."))])])

