pack(28, "C1", T("Advanced 4: Nuance & tact", "Cao cấp 4: Sắc thái & tế nhị"),
     T("Hedge, soften, and say difficult things gracefully.", "Nói giảm, làm mềm và nói điều khó nói một cách khéo léo."),
 [lesson("hedging", T("Hedging & softening", "Nói giảm & làm mềm"), T("Sound careful, not blunt.", "Nói thận trọng, không cộc lốc."), "sliders", [
    ("Quizás no sea la mejor idea.", "Perhaps it isn't the best idea.", "Có lẽ đó không phải ý hay nhất."),
    ("Igual me equivoco, pero…", "I might be wrong, but…", "Có thể tôi sai, nhưng…"),
    ("No es que no me guste, es que…", "It's not that I don't like it, it's that…", "Không phải tôi không thích, mà là…"),
    ("Habría que pensarlo un poco más.", "We'd need to think it over a bit more.", "Có lẽ cần suy nghĩ thêm một chút."),
    ("Por así decirlo…", "So to speak…", "Có thể nói là…"),
    ("No sé si me explico.", "I don't know if I'm making myself clear.", "Không biết tôi nói vậy có rõ không.")],
    focus=T("“Quizás + subjunctive” and “no es que + subjunctive” add doubt and tact: quizás no sea, no es que no me guste.", "“Quizás + giả định” và “no es que + giả định” thêm sự hoài nghi và tế nhị: quizás no sea, no es que no me guste.")),
  lesson("tough-talks", T("Difficult conversations", "Những cuộc nói chuyện khó"), T("Give feedback and apologize well.", "Góp ý và xin lỗi khéo léo."), "shield", [
    ("Te lo digo con todo el cariño.", "I'm saying this with all my affection.", "Tôi nói điều này với tất cả thiện ý."),
    ("Me hubiera gustado que me avisaras.", "I would have liked you to let me know.", "Lẽ ra tôi mong bạn báo trước cho tôi."),
    ("Lamento mucho lo que pasó.", "I'm really sorry about what happened.", "Tôi rất tiếc về những gì đã xảy ra."),
    ("No fue mi intención ofenderte.", "I didn't mean to offend you.", "Tôi không có ý xúc phạm bạn."),
    ("Pongámonos en su lugar.", "Let's put ourselves in their shoes.", "Hãy đặt mình vào vị trí của họ."),
    ("¿Cómo lo podemos resolver?", "How can we solve it?", "Chúng ta giải quyết thế nào đây?")],
    focus=T("“Me hubiera gustado que + past subjunctive” voices disappointment without blaming.", "“Me hubiera gustado que + giả định quá khứ” bày tỏ sự thất vọng mà không đổ lỗi."))],
 [convo("feedback", T("Give honest feedback", "Góp ý thẳng thắn"), T("Tell a friend a hard truth, kindly.", "Nói một sự thật khó nghe với bạn một cách tử tế."), "heart", [
    node("ask", "Sé sincero: ¿qué te pareció mi presentación?", "Be honest: what did you think of my presentation?", "Nói thật đi: bạn thấy bài thuyết trình của mình thế nào?", "Soften before the criticism.", "Làm mềm trước khi góp ý.",
      ok("soft", "Te lo digo con cariño: el contenido era bueno, pero fue un poco larga.", "I say this kindly: the content was good, but it was a bit long.", "Mình nói với thiện ý: nội dung tốt, nhưng hơi dài.", "Ah… ¿muy larga?", "Oh… very long?", "Ồ… dài lắm à?", "detail"),
      ok("hedge", "Igual me equivoco, pero creo que quizás sobraban algunas diapositivas.", "I might be wrong, but maybe there were a few too many slides.", "Có thể mình sai, nhưng có lẽ dư vài slide.", "Mmm, ¿cuáles quitarías?", "Hmm, which would you remove?", "Ừm, bạn sẽ bỏ slide nào?", "detail"),
      bad("blunt", "Fue aburrida.", "It was boring.", "Chán lắm.", "Te lo digo con cariño: el contenido era bueno, pero fue un poco larga.", "Auch… ¿no hubo nada bueno?", "Ouch… was nothing good?", "Đau ghê… không có gì hay sao?", "detail")),
    node("detail", "¿Qué cambiarías?", "What would you change?", "Bạn sẽ thay đổi gì?", "Suggest with tact.", "Gợi ý một cách tế nhị.",
      ok("shorter", "No es que esté mal, es que con diez minutos menos sería perfecta.", "It's not that it's bad, it's that ten minutes shorter would make it perfect.", "Không phải là dở, chỉ là ngắn đi mười phút sẽ hoàn hảo.", "Tiene sentido. ¿Algo más?", "Makes sense. Anything else?", "Hợp lý. Còn gì nữa không?", "end"),
      ok("think", "Habría que pensar qué es lo esencial para el público.", "We'd need to think about what's essential for the audience.", "Có lẽ nên nghĩ xem điều gì là cốt lõi với khán giả.", "Buena idea. ¿Algo más?", "Good idea. Anything else?", "Ý hay. Còn gì nữa không?", "end"),
      bad("mood", "No es que está mal…", "It's not that it is bad… (wrong form)", "Không phải là dở… (sai dạng)", "No es que esté mal, es que con diez minutos menos sería perfecta.", "Entiendo (“no es que esté”, ¿no?). ¿Algo más?", "I get it (“no es que esté”, right?). Anything else?", "Mình hiểu (phải là “no es que esté” chứ?). Còn gì nữa không?", "end")),
    node("end", "Gracias por ser honesto.", "Thanks for being honest.", "Cảm ơn bạn đã thẳng thắn.", "Close warmly.", "Kết thúc ấm áp.",
      ok("proud", "Para eso estamos. Y de verdad, se nota que te preparaste mucho.", "That's what friends are for. And honestly, it shows you prepared a lot.", "Bạn bè mà. Thật sự là thấy rõ bạn đã chuẩn bị rất kỹ.", "Eso me anima mucho.", "That really encourages me.", "Nghe vậy mình có động lực hẳn."),
      ok("help", "Si quieres, la practicamos juntos mañana.", "If you want, we can practice it together tomorrow.", "Nếu muốn, mai mình luyện cùng nhau.", "¡Me encantaría!", "I'd love that!", "Mình rất muốn!"),
      bad("sorry", "No fue mi intención ofenderte.", "I didn't mean to offend you.", "Mình không có ý xúc phạm bạn.", "Para eso estamos. Y de verdad, se nota que te preparaste mucho.", "No me ofendiste, ¡al contrario!", "You didn't offend me, quite the opposite!", "Bạn đâu có xúc phạm mình, ngược lại thì có!"))])])

